INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-T001-SEADTL', 'HDSAT-RW-M14-WB-T001-SEADTL', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A regional education office is describing the adult literacy rate in India using World Bank figures for 2019 through 2023.', 'Which statement about the graphed change is supported by the data?', '[{"id": "A", "text": "It rose through 2021 but then fell in both 2022 and 2023."}, {"id": "B", "text": "It fell in every year shown."}, {"id": "C", "text": "It was essentially flat: the 2023 figure was within half a percentage point of the 2019 figure."}, {"id": "D", "text": "Between 2019 and 2023, India''s adult literacy rate rose in every year shown, from 74.9% to 81.7%."}]'::jsonb, '{"type": "line_chart", "caption": "Adult literacy rate in India, 2019-2023", "x_label": "Year", "y_label": "Adult literacy rate (%)", "series": [{"label": "2019", "value": 74.9}, {"label": "2020", "value": 75.5}, {"label": "2021", "value": 76.1}, {"label": "2022", "value": 76.3}, {"label": "2023", "value": 81.7}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, li