INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M14-WB-T001-SEADTL', 'D', ARRAY['D']::TEXT[], 'The graph''s five points move in one direction throughout, from 74.9% in 2019 to 81.7% in 2023.', '{"B": "The series does not move in that direction at any point.", "A": "There is no reversal after 2021; the change keeps the same sign.", "C": "The endpoints differ by 6.8 percentage points, far more than half a percentage point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-C001-SEADTL', 'HDSAT-RW-M14-WB-C001-SEADTL', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A regional education office compares the adult literacy rate in four countries using World Bank figures for 2018.', 'Which choice most effectively uses data from the table to compare the countries?', '[{"id": "A", "text": "In 2018, all four countries reported the adult literacy rate within one percentage point of one another."}, {"id": "B", "text": "In 2018, Indonesia had the highest adult literacy rate at 95.7%, while India had the lowest at 73.7%."}, {"id": "C", "text": "In 2018, Brazil reported the highest adult literacy rate of the four countries."}, {"id": "D", "text": "In 2018, India''s adult literacy rate was higher than Indonesia''s, though both appear in the table."}]'::jsonb, '{"type": "table", "caption": "Adult literacy rate in 2018", "headers": ["Country", "Adult literacy rate (%)"], "rows": [["Indonesia", "95.7%"], ["Mexico", "95.4%"], ["Brazil", "93.2%"], ["India", "73.7%"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, 