INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-P001-ITNETU', 'HDSAT-RW-M14-WB-P001-ITNETU', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A telecommunications report has compiled internet use for Indonesia in four years, taken from World Bank figures.', 'Which choice most accurately states the highest and lowest values in the table?', '[{"id": "A", "text": "All four values fall within one % of one another, so the table shows no real variation."}, {"id": "B", "text": "The lowest value in the table is 69.2% in 2023."}, {"id": "C", "text": "The highest value in the table is 10.9% in 2010."}, {"id": "D", "text": "The highest value in the table is 69.2% in 2023, and the lowest is 10.9% in 2010."}]'::jsonb, '{"type": "table", "caption": "Internet use in Indonesia", "headers": ["Year", "Internet use (%)"], "rows": [["2010", "10.9%"], ["2014", "17.1%"], ["2019", "47.7%"], ["2023", "69.2%"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M14-WB-P001-ITNETU', 'D', ARRAY['D']::TEXT[], 'Reading the table, 2023 shows the largest figure (69.2%) and 2010 the smallest (10.9%); the spread is 58.3 percentage points.', '{"C": "That row holds the smallest figure, not the largest.", "B": "That row holds the largest figure, not the smallest.", "A": "The spread is 58.3 percentage points, so the values are not clustered."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-B001-ITNETU', 'HDSAT-RW-M14-WB-B001-ITNETU', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A telecommunications report is reviewing how internet use changed in four countries between 2010 and 2015, using World Bank figures.', 'Which choice most effectively uses data from the graph?', '[{"id": "A", "text": "Brazil had the largest increase, gaining 17.7 percentage points."}, {"id": "B", "text": "Mexico''s internet use fell by 26.3 percentage points over the period."}, {"id": "C", "text": "Mexico had the largest increase, rising from 31.1% in 2010 to 57.4% in 2015, a gain of 26.3 percentage points."}, {"id": "D", "text": "Mexico had the largest increase, gaining 27.8 percentage points."}]'::jsonb, '{"type": "bar_chart", "caption": "Change in internet use, 2010 to 2015", "x_label": "Country", "y_label": "Change (percentage points)", "series": [{"label": "Mexico", "value": 26.3}, {"label": "Brazil", "value": 17.7}, {"label": "Japan", "value": 12.9}, {"label": "Indonesia", "value": 11.2}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M14-WB-B001-ITNETU', 'C', ARRAY['C']::TEXT[], 'Mexico moved from 31.1% to 57.4%, the steepest rise in the group at 26.3 percentage points; every other country''s change is smaller.', '{"A": "Brazil gains 17.7 percentage points, below Mexico''s 26.3 percentage points.", "D": "The stated gain for Mexico overstates the data by 1.5 percentage points.", "B": "Mexico''s figure rises rather than falls, so the direction is wrong."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-B002-ITNETU', 'HDSAT-RW-M14-WB-B002-ITNETU', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A telecommunications report is reviewing how internet use changed in four countries between 2015 and 2020, using World Bank figures.', 'Which statement about the change in internet use is supported by the graph?', '[{"id": "A", "text": "India had the largest increase, gaining 28.5 percentage points."}, {"id": "B", "text": "Indonesia had the largest increase, gaining 33.1 percentage points."}, {"id": "C", "text": "Indonesia''s internet use fell by 31.6 percentage points over the period."}, {"id": "D", "text": "Indonesia had the largest increase, rising from 22.1% in 2015 to 53.7% in 2020, a gain of 31.6 percentage points."}]'::jsonb, '{"type": "bar_chart", "caption": "Change in internet use, 2015 to 2020", "x_label": "Country", "y_label": "Change (percentage points)", "series": [{"label": "Indonesia", "value": 31.6}, {"label": "India", "value": 28.5}, {"label": "Brazil", "value": 23.0}, {"label": "United States", "value": 15.7}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id