INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-T001-EGELCR', 'HDSAT-RW-M14-WB-T001-EGELCR', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'An energy bulletin is describing the renewable share of electricity in India using World Bank figures for 2017 through 2021.', 'Which statement about the graphed change is supported by the data?', '[{"id": "A", "text": "The 2021 figure was lower than the 2017 figure."}, {"id": "B", "text": "After the change in 2021, the series never recovered its 2017 level."}, {"id": "C", "text": "Although India''s renewable share of electricity moved against the trend in 2021, it rose overall between 2017 and 2021, from 14.2% to 19.1%."}, {"id": "D", "text": "It rose in every year shown, with no exception."}]'::jsonb, '{"type": "line_chart", "caption": "Renewable share of electricity in India, 2017-2021", "x_label": "Year", "y_label": "Renewable share of electricity (%)", "series": [{"label": "2017", "value": 14.2}, {"label": "2018", "value": 15.0}, {"label": "2019", "value": 16.8}, {"label": "2020", "value": 19.8}, {"label": "2021", "value": 19.1}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.