INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M14-WB-T001-EGELCR', 'C', ARRAY['C']::TEXT[], 'The series ends 4.9 % rose than it began, and the single move against the trend comes in 2021.', '{"D": "The move in 2021 breaks the year-by-year pattern, so the trend is not unbroken.", "A": "The final value is 19.1%, which is above the opening 14.2%.", "B": "The 2021 figure is rose than the 2017 figure, so the level was recovered and surpassed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
