INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M14-WB-T002-EGELCR', 'D', ARRAY['D']::TEXT[], 'The graph''s five points move in one direction throughout, from 16.2% in 2017 to 21.1% in 2021.', '{"C": "The series does not move in that direction at any point.", "B": "There is no reversal after 2019; the change keeps the same sign.", "A": "The endpoints differ by 4.9 percentage points, far more than half a percentage point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
