INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-P001-EGELCR', 'HDSAT-RW-M14-WB-P001-EGELCR', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'An energy bulletin has compiled the renewable share of electricity for Indonesia in four years, taken from World Bank figures.', 'Which choice most accurately states the highest and lowest values in the table?', '[{"id": "A", "text": "All four values fall within one % of one another, so the table shows no real variation."}, {"id": "B", "text": "The highest value in the table is 14.5% in 2014."}, {"id": "C", "text": "The lowest value in the table is 19.5% in 2010."}, {"id": "D", "text": "The highest value in the table is 19.5% in 2010, and the lowest is 14.5% in 2014."}]'::jsonb, '{"type": "table", "caption": "Renewable share of electricity in Indonesia", "headers": ["Year", "Renewable share of electricity (%)"], "rows": [["2010", "19.5%"], ["2014", "14.5%"], ["2018", "15.6%"], ["2021", "15.5%"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCL