INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M14-WB-B001-EGELCR', 'HDSAT-RW-M14-WB-B001-EGELCR', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'An energy bulletin is reviewing how the renewable share of electricity changed in four countries between 2010 and 2015, using World Bank figures.', 'Which choice most effectively uses data from the graph?', '[{"id": "A", "text": "Kenya had the largest increase, gaining 24.4 percentage points."}, {"id": "B", "text": "Germany had the largest increase, gaining 12.4 percentage points."}, {"id": "C", "text": "Kenya''s renewable share of electricity fell by 22.9 percentage points over the period."}, {"id": "D", "text": "Kenya had the largest increase, rising from 62.7% in 2010 to 85.6% in 2015, a gain of 22.9 percentage points."}]'::jsonb, '{"type": "bar_chart", "caption": "Change in renewable share of electricity, 2010 to 2015", "x_label": "Country", "y_label": "Change (percentage points)", "series": [{"label": "Kenya", "value": 22.9}, {"label": "Germany", "value": 12.4}, {"label": "Japan", "value": 4.5}, {"label": "United States", "value": 3.0}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'Data: World Bank Open Data (CC BY 4.0), worldbank.org. Item text: HDSAT Open Core (CC BY-4.0).', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCL