INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M14-WB-B001-SPURBT', 'C', ARRAY['C']::TEXT[], 'Nigeria moved from 51.7% to 55.7%, the steepest rise in the group at 4.0 percentage points; every other country''s change is smaller.', '{"A": "Indonesia gains 3.3 percentage points, below Nigeria''s 4.0 percentage points.", "B": "The stated gain for Nigeria overstates the data by 1.5 percentage points.", "D": "Nigeria''s figure rises rather than falls, so the direction is wrong."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
